fun validateTeamNumber(number: Int): Int {
    require(number in 1..9999) { "Team number must be between 1 and 9999" }
    return number
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testValidTeamNumber() {
        Assert.assertEquals(4215, validateTeamNumber(4215))
    }

    @Test
    fun testMinTeamNumber() {
        Assert.assertEquals(1, validateTeamNumber(1))
    }

    @Test
    fun testMaxTeamNumber() {
        Assert.assertEquals(9999, validateTeamNumber(9999))
    }

    @Test
    fun testZeroMessage() {
        try {
            validateTeamNumber(0)
            Assert.fail("Should have thrown IllegalArgumentException")
        } catch (e: IllegalArgumentException) {
            Assert.assertEquals("Team number must be between 1 and 9999", e.message)
        }
    }

    @Test(expected = IllegalArgumentException::class)
    fun testNegative() {
        validateTeamNumber(-1)
    }

    @Test(expected = IllegalArgumentException::class)
    fun testTooLarge() {
        validateTeamNumber(10000)
    }
}
